local NB = #BONE_ORDER
local PIV, OFF, PARI = {}, {}, {}
local BIDX = {}
for i, bn in ipairs(BONE_ORDER) do BIDX[bn] = i end
for i, bn in ipairs(BONE_ORDER) do
	PIV[i] = PIV_M[bn] * U
	local p = PARENT[bn]
	PARI[i] = p and BIDX[p] or nil
	OFF[i] = p and (PIV_M[bn] - PIV_M[p]) * U or ZERO
end

local ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local MAP = {}
for i = 1, 64 do MAP[ALPHA:byte(i)] = i - 1 end
local function decodeClip(c)
	local s, p = c.data, 1
	local function rd(n)
		local v = 0
		for _ = 1, n do v = v * 64 + MAP[s:byte(p)] p = p + 1 end
		return v
	end
	c.f = {}
	for f = 1, c.n do
		local hx, hy, hz = (rd(3) - 131072) * 0.002 * U, (rd(3) - 131072) * 0.002 * U, (rd(3) - 131072) * 0.002 * U
		local rx, rz = (rd(3) - 131072) * 0.001 * U, (rd(3) - 131072) * 0.001 * U
		local rot = {}
		for i = 1, NB do
			local v = rd(6)
			local m = math.floor(v / 1073741824)
			local cs = {
				(math.floor(v / 1048576) % 1024) / 1023 * 1.4144 - 0.7072,
				(math.floor(v / 1024) % 1024) / 1023 * 1.4144 - 0.7072,
				(v % 1024) / 1023 * 1.4144 - 0.7072,
			}
			local qq, ii = { 0, 0, 0, 0 }, 1
			for t = 1, 4 do
				if t - 1 ~= m then qq[t] = cs[ii] ii = ii + 1 end
			end
			qq[m + 1] = math.sqrt(math.max(0, 1 - (cs[1] ^ 2 + cs[2] ^ 2 + cs[3] ^ 2)))
			rot[i] = CF(0, 0, 0, qq[1], qq[2], qq[3], qq[4])
		end
		c.f[f] = { hip = V(hx, hy, hz), rm = V(rx, 0, rz), rot = rot }
		if f % 3 == 0 then task.wait() end
	end
	c.dur = c.n / c.fps
end
say("decoding animation clips...")
for _, c in pairs(CLIPS) do decodeClip(c) end

local function samplePose(c, t, out)
	local n = c.n
	local x, i0, i1 = t * c.fps, 0, 0
	if c.loop then
		x = x % n
		i0 = math.floor(x)
		i1 = (i0 + 1) % n
	else
		x = math.clamp(x, 0, n - 1)
		i0 = math.floor(x)
		i1 = math.min(i0 + 1, n - 1)
	end
	local a = x - i0
	local f0, f1 = c.f[i0 + 1], c.f[i1 + 1]
	for i = 1, NB do out.rot[i] = f0.rot[i]:Lerp(f1.rot[i], a) end
	out.hip = f0.hip:Lerp(f1.hip, a)
	out.rm = f0.rm:Lerp(f1.rm, a)
end

----------------------------------------------------------------------
-- STATE
----------------------------------------------------------------------
local function unit(v, fb) local m = v.Magnitude if m < 1e-6 then return fb or V(0, 0, -1) end return v / m end
local function wrap(a) return (a + math.pi) % (2 * math.pi) - math.pi end

local rayParams
local function listExclude()
	local l = { Character, aircraft }
	for _, pl2 in ipairs(Players:GetPlayers()) do if pl2.Character then table.insert(l, pl2.Character) end end
	return l
end
rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.FilterDescendantsInstances = listExclude()

local function groundBelow(p, maxLen)
	local len = math.min(maxLen or 400, p.Y - (Workspace.FallenPartsDestroyHeight + 20))
	if len <= 0 then return nil end
	local res = Workspace:Raycast(p, V(0, -len, 0), rayParams)
	return res and res.Position.Y or nil
end

local pos = (RealRoot.CFrame * CF(0, 0, -CFG.SPAWN_DIST)).Position
local yaw
do
	local lv = RealRoot.CFrame.LookVector
	yaw = math.atan2(-lv.X, -lv.Z) + math.pi   -- face the player
	local g = groundBelow(pos + V(0, 60, 0))
	pos = V(pos.X, g or pos.Y, pos.Z)
end

RealHum.WalkSpeed = 0
RealHum.AutoRotate = false
local oldAnimate = Character:FindFirstChild("Animate")
if oldAnimate then oldAnimate.Disabled = true end
do
	local animator = RealHum:FindFirstChildOfClass("Animator")
	if animator then
		for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do tr:Stop(0) end
	end
end

camPart = Instance.new("Part")
camPart.Name = "TyrantCam"
camPart.Anchored = true
camPart.CanCollide = false
camPart.CanQuery = false
camPart.Transparency = 1
camPart.Size = V(1, 1, 1)
camPart.Parent = Workspace
Player.CameraMaxZoomDistance = 400
Player.CameraMinZoomDistance = CFG.CAM_MIN
Workspace.CurrentCamera.CameraSubject = camPart

local actions, runToggle = {}, false
local cur = { name = "idle", t = 0 }
local fade = { from = {}, k = 1 }
local pose = { rot = {}, hip = ZERO, rm = ZERO }
local last = { rot = {}, hip = ZERO }
for i = 1, NB do pose.rot[i], last.rot[i], fade.from[i] = CFrame.identity, CFrame.identity, CFrame.identity end
local act = nil
local spd, clockT = 0, 0
local Fr = {}
local bulkParts, bulkCFs, lastN = {}, {}, 0
local moveAcc, fastCam, hideT = 0, 0, 0

local function pruneDead()
	local keep, nb, live = {}, {}, 0
	for _, f in ipairs(followers) do
		if f.part.Parent then keep[#keep + 1] = f end
	end
	for bone, d in pairs(drivers) do
		if d.part.Parent and d.bp and d.bg then
			nb[bone] = { d }
			live = live + 1 + #d.group
		end
	end
	followers, byBone = keep, nb
	return live
end

local function setClip(name)
	if cur.name == name then return end
	for i = 1, NB do fade.from[i] = last.rot[i] end
	fade.fromHip, fade.k = last.hip, 0
	cur.name, cur.t = name, 0
end

local ACT = { ATK1 = "att1", ATK2 = "att2", HEAVY = "att3", GRAB = "grab", TAUNT1 = "taunt1", TAUNT2 = "taunt2", TAUNT3 = "taunt3", RISE = "rise", SPAWN = "spawn" }
local NOAIM = { TAUNT1 = true, TAUNT2 = true, TAUNT3 = true, RISE = true, SPAWN = true }
local forced = nil   -- { name, untilT }: preview idle/walk/run on demand
local function startAct(kind)
	if act then return end
	local clip = ACT[kind]
	if not clip then return end
	forced = nil
	if not NOAIM[kind] then
		local lv = Workspace.CurrentCamera.CFrame.LookVector
		if V(lv.X, 0, lv.Z).Magnitude > 0.05 then yaw = math.atan2(-lv.X, -lv.Z) end   -- strike where you look
	end
	setClip(clip)
	cur.t = 0
	act = { clip = clip, t = 0, prevRm = ZERO, dur = CLIPS[clip].dur }
end

-- one function per animation (also exposed as getgenv().TyrantAnim)
local Anim = {}
function Anim.att1() startAct("ATK1") end
function Anim.att2() startAct("ATK2") end
function Anim.att3() startAct("HEAVY") end
function Anim.grab() startAct("GRAB") end
function Anim.taunt1() startAct("TAUNT1") end
function Anim.taunt2() startAct("TAUNT2") end
function Anim.taunt3() startAct("TAUNT3") end
function Anim.taunt() startAct("TAUNT3") end
function Anim.rise() startAct("RISE") end
function Anim.spawn() startAct("SPAWN") end
function Anim.idle(sec) forced = { name = "idle", untilT = clockT + (sec or 4) } end
function Anim.walk(sec) forced = { name = "walk", untilT = clockT + (sec or 4) } end
function Anim.run(sec) forced = { name = "run", untilT = clockT + (sec or 4) } end
G.TyrantAnim = Anim

local function moveWithWalls(delta)
	if delta.Magnitude < 1e-4 then return end
	local from = pos + V(0, 7, 0)
	local r = Workspace:Raycast(from, unit(delta) * (delta.Magnitude + CFG.BODY_RADIUS), rayParams)
	if r and math.abs(r.Normal.Y) < 0.6 then
		delta = delta - r.Normal * delta:Dot(r.Normal)
		local r2 = Workspace:Raycast(from, unit(delta, ZERO) * (delta.Magnitude + CFG.BODY_RADIUS), rayParams)
		if r2 and math.abs(r2.Normal.Y) < 0.6 then return end
	end
	pos = pos + delta
end

-- touch / mouse buttons (local UI only; they feed the same inputs as keyboard and gamepad)
do
	local mainDefs = {  -- name, label, x offset, y offset, size
		{ "ATK1", "SWING 1", -100, -140, 88 }, { "ATK2", "SWING 2", -200, -100, 76 }, { "HEAVY", "HEAVY", -100, -245, 76 },
		{ "GRAB", "GRAB", -205, -205, 70 }, { "MORE", "MORE", -300, -150, 64 }, { "RUN", "RUN", -90, -340, 64 },
	}
	local moreDefs = {
		{ "TAUNT1", "TAUNT 1", -300, -235, 64 }, { "TAUNT2", "TAUNT 2", -300, -310, 64 }, { "TAUNT3", "TAUNT 3", -300, -385, 64 },
		{ "RISE", "RISE", -380, -150, 64 }, { "SPAWN", "SPAWN", -380, -225, 64 },
	}
	local moreBtns = {}
	local function mk(d, isMore)
		local nm, sz = d[1], d[5]
		local b = Instance.new("TextButton")
		b.Size = UDim2.new(0, sz, 0, sz)
		b.AnchorPoint = Vector2.new(0.5, 0.5)
		b.Position = UDim2.new(1, d[3], 1, d[4])
		b.BackgroundColor3 = nm == "ATK1" and Color3.fromRGB(120, 24, 24) or Color3.fromRGB(20, 22, 30)
		b.BackgroundTransparency = 0.25
		b.TextColor3 = Color3.new(1, 1, 1)
		b.Font = Enum.Font.GothamBold
		b.TextSize = 12
		b.Text = d[2]
		b.Visible = not isMore
		local cr = Instance.new("UICorner") cr.CornerRadius = UDim.new(1, 0) cr.Parent = b
		b.Parent = hud
		if isMore then moreBtns[#moreBtns + 1] = b end
		track(b.InputBegan:Connect(function(inp)
			if inp.UserInputType ~= Enum.UserInputType.Touch and inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
			if nm == "RUN" then
				runToggle = not runToggle
				b.BackgroundColor3 = runToggle and Color3.fromRGB(30, 110, 40) or Color3.fromRGB(20, 22, 30)
			elseif nm == "MORE" then
				local on = not moreBtns[1].Visible
				for _, mb in ipairs(moreBtns) do mb.Visible = on end
			else
				actions[nm] = true
			end
		end))
	end
	for _, d in ipairs(moreDefs) do mk(d, true) end
	for _, d in ipairs(mainDefs) do mk(d, false) end
end

----------------------------------------------------------------------
-- MAIN LOOP
----------------------------------------------------------------------
local function frame(dt)
	dt = math.min(dt, 0.1)
	clockT = clockT + dt
	local cam = Workspace.CurrentCamera

	-- ===== actions =====
	for k in pairs(ACT) do
		if actions[k] then actions[k] = nil startAct(k) end
	end
	if forced and clockT > forced.untilT then forced = nil end

	local md = RealHum.MoveDirection
	local mag = md.Magnitude
	local running = runToggle or UIS:IsKeyDown(Enum.KeyCode.LeftShift)

	local clipName
	if act then
		act.t = act.t + dt
		cur.t = act.t
		clipName = act.clip
	else
		-- turn towards the move direction, walk/run, idle when still
		local want = 0
		if mag > 0.1 then
			local ty = math.atan2(-md.X, -md.Z)
			local diff = wrap(ty - yaw)
			yaw = yaw + math.clamp(diff, -CFG.TURN_RATE * dt, CFG.TURN_RATE * dt)
			want = (running and CFG.RUN_SPEED or CFG.WALK_SPEED) * math.min(1, mag * 1.2) * math.max(0, 1 - math.abs(diff) / 1.6)
		end
		spd = spd + (want - spd) * math.min(1, dt * CFG.ACCEL)
		if spd < 0.4 then spd = 0 end
		if spd > 0 then moveWithWalls(V(-math.sin(yaw), 0, -math.cos(yaw)) * spd * dt) end
		if spd <= 0.5 then clipName = "idle"
		elseif spd > CFG.WALK_SPEED * 1.35 then clipName = "run"
		else clipName = "walk" end
		if forced and spd <= 0.5 then clipName = forced.name end
		setClip(clipName)
		local c = CLIPS[clipName]
		local rate = 1
		if c.stride > 0 then rate = spd > 0.5 and math.clamp(spd / (c.stride * U), 0.4, 3) or 1 end
		cur.t = cur.t + dt * rate
	end

	-- ===== pose =====
	local c = CLIPS[cur.name]
	samplePose(c, cur.t, pose)
	if act then
		local d = pose.rm - act.prevRm
		act.prevRm = pose.rm
		moveWithWalls(CFrame.Angles(0, yaw, 0):VectorToWorldSpace(d))
		if act.t >= act.dur then act = nil setClip(running and "walk" or "idle") end
	end
	local outRot, outHip = pose.rot, pose.hip
	if fade.k < 1 then
		fade.k = math.min(1, fade.k + dt / CFG.FADE)
		local k = fade.k * fade.k * (3 - 2 * fade.k)
		for i = 1, NB do last.rot[i] = fade.from[i]:Lerp(pose.rot[i], k) end
		last.hip = (fade.fromHip or pose.hip):Lerp(pose.hip, k)
	else
		for i = 1, NB do last.rot[i] = pose.rot[i] end
		last.hip = pose.hip
	end
	outRot, outHip = last.rot, last.hip

	-- ground follow
	local gy = groundBelow(pos + V(0, 8, 0))
	if gy then pos = V(pos.X, pos.Y + (gy - pos.Y) * math.min(1, dt * 14), pos.Z) end

	-- ===== forward kinematics =====
	local root = CF(pos) * CFrame.Angles(0, yaw, 0)
	local W = {}
	for i = 1, NB do
		local p = PARI[i]
		local F
		if p then F = Fr[p] * CF(OFF[i]) * outRot[i]
		else F = root * CF(PIV[i] + outHip) * outRot[i] end
		Fr[i] = F
		W[BONE_ORDER[i]] = F * CF(-PIV[i])
	end

	-- ===== push bone drivers (welded plates follow their driver on the server) =====
	moveAcc = moveAcc + dt
	if moveAcc >= 1 / CFG.UPDATE_HZ then
		moveAcc = 0
		local cnt = 0
		for _, bn in ipairs(BONE_ORDER) do
			local list = byBone[bn]
			local Wb = W[bn]
			if list and Wb then
				for i = 1, #list do
					local f = list[i]
					local cf = Wb * f.cf
					cnt = cnt + 1
					bulkParts[cnt], bulkCFs[cnt] = f.part, cf
					f.bp.Position = cf.Position
					f.bg.CFrame = cf
				end
			end
		end
		for i = cnt + 1, lastN do bulkParts[i], bulkCFs[i] = nil, nil end
		lastN = cnt
		if cnt > 0 then
			local ok = pcall(Workspace.BulkMoveTo, Workspace, bulkParts, bulkCFs, Enum.BulkMoveMode.FireCFrameChanged)
			if not ok then
				local left = pruneDead()
				lastN = 0
				if left < count * 0.5 then shutdown("the plane was despawned") return end
			end
		end
	end

	-- ===== camera target + keep the real character hidden INSIDE the body =====
	camPart.CFrame = CF(pos + V(0, CFG.CAM_HEIGHT, 0))
	RealRoot.Anchored = true
	RealRoot.CFrame = Fr[BIDX.chest] or root
	RealRoot.AssemblyLinearVelocity = ZERO
	hideT = hideT + dt
	if hideT > 0.25 then
		hideT = 0
		for _, d in ipairs(Character:GetDescendants()) do
			if d:IsA("BasePart") then
				d.CanCollide = false
				if CFG.HIDE_SELF then d.LocalTransparencyModifier = 1 end
			end
		end
	end
	fastCam = fastCam + dt
	if fastCam > 1 then
		fastCam = 0
		rayParams.FilterDescendantsInstances = listExclude()
		if cam.CameraSubject ~= camPart then cam.CameraSubject = camPart end
	end
end

local errCount = 0
track(RunService.Heartbeat:Connect(function(dt)
	if not alive then return end
	local ok, err = pcall(frame, dt)
	if ok then errCount = 0
	else
		errCount = errCount + 1
		if errCount == 1 then warn("[Tyrant] frame error: " .. tostring(err)) end
		if errCount > 90 then shutdown("too many errors: " .. tostring(err)) end
	end
end))

----------------------------------------------------------------------
-- INPUT (keyboard / mouse / gamepad; touch uses the on-screen buttons + the default thumbstick)
----------------------------------------------------------------------
track(UIS.InputBegan:Connect(function(input, gp)
	if gp or not alive then return end
	local k = input.KeyCode
	if input.UserInputType == Enum.UserInputType.MouseButton1 or k == Enum.KeyCode.F or k == Enum.KeyCode.ButtonX then actions.ATK1 = true
	elseif k == Enum.KeyCode.Q or k == Enum.KeyCode.ButtonR2 then actions.ATK2 = true
	elseif k == Enum.KeyCode.E or k == Enum.KeyCode.ButtonY then actions.HEAVY = true
	elseif k == Enum.KeyCode.R or k == Enum.KeyCode.ButtonB then actions.GRAB = true
	elseif k == Enum.KeyCode.T or k == Enum.KeyCode.ButtonR1 then actions.TAUNT1 = true
	elseif k == Enum.KeyCode.Y or k == Enum.KeyCode.DPadLeft then actions.TAUNT2 = true
	elseif k == Enum.KeyCode.U or k == Enum.KeyCode.DPadRight then actions.TAUNT3 = true
	elseif k == Enum.KeyCode.G or k == Enum.KeyCode.DPadUp then actions.RISE = true
	elseif k == Enum.KeyCode.Z or k == Enum.KeyCode.DPadDown then actions.SPAWN = true
	elseif k == Enum.KeyCode.One then Anim.idle()
	elseif k == Enum.KeyCode.Two then Anim.walk()
	elseif k == Enum.KeyCode.Three then Anim.run()
	elseif k == Enum.KeyCode.ButtonL3 then runToggle = not runToggle
	elseif k == Enum.KeyCode.H then hudLabel.Visible = not hudLabel.Visible
	elseif k == Enum.KeyCode.P then shutdown("P pressed")
	end
end))

----------------------------------------------------------------------
-- WATCHDOG
----------------------------------------------------------------------
track(RealHum.Died:Connect(function() shutdown("you died") end))
track(Player.CharacterAdded:Connect(function() shutdown("respawned") end))
track(Character.AncestryChanged:Connect(function(_, parent) if not parent then shutdown("character removed") end end))
track(aircraft.AncestryChanged:Connect(function(_, parent) if not parent then shutdown("plane despawned") end end))
task.spawn(function()
	while alive do
		task.wait(0.25)
		if not aircraft.Parent or not aircraft:IsDescendantOf(Workspace) then shutdown("plane despawned") break end
		if not Character.Parent or RealHum.Health <= 0 then shutdown("character gone") break end
	end
end)

startAct("SPAWN")
say("Tyrant T-501 online.")
say("Move: thumbstick / WASD | RUN: SHIFT | SWING 1: LMB/F | SWING 2: Q | HEAVY: E | GRAB: R | TAUNT 1/2/3: T/Y/U | RISE: G | SPAWN: Z | 1/2/3 preview idle/walk/run")
say("Gamepad: X swing1, R2 swing2, Y heavy, B grab, R1 taunt1, DPad L/R taunt2/3, DPad U rise, DPad D spawn, L3 run | H hud | P stop | console: getgenv().TyrantAnim.att1/att2/att3/grab/taunt1/taunt2/taunt3/rise/spawn/idle/walk/run()")
end

runtime()

end
main()

